current_sums = {}
for line in result_current_sums.stdout.strip().split('\n'):
    parts = line.strip().split('  ', 1)
    if len(parts) == 2:
        current_sums[parts[1]] = parts[0]

print(f"Backup SHA256SUMS entries: {len(backup_sums)}")
print(f"Current SHA256SUMS entries: {len(current_sums)}")

# Find differences between backup and current SHA256SUMS
print("\n=== Files where SHA256SUMS hash changed (backup -> current) ===")
changed_in_sums = []
for f, h in backup_sums.items():
    if f in current_sums and current_sums[f] != h:
        changed_in_sums.append((f, h, current_sums[f]))
        print(f"  {f}")
        print(f"    backup hash:  {h}")
        print(f"    current hash: {current_sums[f]}")

print(f"\nFiles with changed SHA256SUMS entry: {len(changed_in_sums)}")

print("\n=== Files in backup but not in current SHA256SUMS ===")
for f in backup_sums:
    if f not in current_sums:
        print(f"  REMOVED: {f}")

print("\n=== Files in current SHA256SUMS but not in backup ===")
